INSERT INTO `page_text` (`entry`,`text`,`next_page`) VALUES
(4546,'Ten thousand years ago, Emperor Shaohao, the Last Emperor of Pandaria, used the power of these sacred waters to spare Pandaria from the devastation of the Sundering that destroyed the rest of the world.',0),
(4605,'Nodding, the General withdrew a coin from his pocket. "Let us see how the winds blow!" he said, tossing the coin into the air. "If it is heads, our defense will hold. If it is tails, the wall will be overrun."$B$BBy now, many of his men had gathered to see the outcome, and a crowd of soldiers eagerly pressed forward to watch the coin land. It bounced, spun, and came to rest. Heads! Cheers erupted.$B$BThe next day battle was fought. The mantid swarmed and the defenders prevailed. Outnumbered thirty to one, the defenders were victorious.',0),
(4610,'At that moment, thunder and lightning tore open the sky as if it were a sheet, and a great rain poured down. The little boat soon became swamped and flipped over. Casting off his overcoat, the Angler began swimming for the shore.$B$B"Help us!" the monks called out, as the swells began to crash around them. "We cannot swim!"The Angler answered: "It would seem to me that you have wasted your lives!"',0);
